// sukunaShinjukuSkins.js — Ryomen Sukuna (Shinjuku Arc) (sukuna_shinjuku): default + premade skins. COSMETIC ONLY.
// Sheets are PRECOMPUTED by tools/sukunaskins/build.py → assets/sukuna_shinjuku/skins/<tag>/ (same frames, size, alpha,
// anchors → identical timing / hitboxes). Nothing is recoloured at runtime. Each skin also ships premade TECHNIQUE effect
// variants (fx/dismantleCut, fx/fugaArrow, fx/cleaveStreak, fx/worldBlades) and a small palette for the procedural
// strokes (web crack, fire patch tongues, explosion ring, contact edge), all generated by the same tool.
// GLITTER skins carry 3 pre-baked glint phases (<tag>/, <tag>/p1/, <tag>/p2/); the phase is picked from the SIMULATION
// clock (never wall-clock), so LAN, replay and companion show the same glint.
// Ids are prefixed "sks_", never END in "AlienX" (game.js's generic starfield matches that suffix) and never contain
// "cyborg" (Superman's eye overlay matches it).
import { sukuna_shinjuku } from './sukunaShinjukuData.js'
import { preloadSheets } from './sprite.js'
import { SKS_SKIN_TABLE } from './sukunaShinjukuSkinTable.js'

export { SKS_SKIN_TABLE }
const PREFIX = 'sks_'
const BY_TAG = Object.fromEntries(SKS_SKIN_TABLE.map(r => [r.tag, r]))
export const sksSkinTag = id => (typeof id === 'string' && id.startsWith(PREFIX) && BY_TAG[id.slice(PREFIX.length)]) ? id.slice(PREFIX.length) : null

// default technique palette (the sheet's own colours)
export const SKS_DEFAULT_PAL = { cutTrail: '#f2c9bd', cleaveEdge: '#fff4ee', cleaveAccent: '#c46b5f', fugaCore: '#fff35a', fugaRim: '#ff3b0a', web: '#3a2a26', amp: '#e9e4ff' }

const _anim = new Map()
export function sksSkinAnim(tag, phase = 0) {
  const k = tag + '|' + phase
  if (_anim.has(k)) return _anim.get(k)
  const dir = `./assets/sukuna_shinjuku/skins/${tag}/${phase ? 'p' + phase + '/' : ''}`
  const out = Object.fromEntries(Object.entries(sukuna_shinjuku.animationData).map(([key, d]) =>
    [key, d?.sheet && d.sheet.startsWith('./assets/sukuna_shinjuku/') && !d.sheet.includes('/fx/') ? { ...d, sheet: d.sheet.replace('./assets/sukuna_shinjuku/', dir) } : d]))
  _anim.set(k, out)
  return out
}

const common = { unlockLevel: 0, cosmeticOnly: true, spriteScale: sukuna_shinjuku.spriteScale }
export const SKS_SKINS = [
  { ...common, id: 'default', name: 'Default (Shinjuku)', classification: 'Default', portrait: sukuna_shinjuku.portrait, animationData: null },
  ...SKS_SKIN_TABLE.map(r => ({ ...common, id: PREFIX + r.tag, name: r.name, classification: r.classification, glitter: !!r.glitter,
    inspired: !!r.crossover, crossover: r.crossover || null,
    source: { version: r.crossover ? `${r.crossover} — colour scheme on Sukuna's own pixels (inspired, not official art)` : 'Original cosmetic design', base: 'Sukuna Shinjuku sheet, recoloured by tools/sukunaskins/build.py' },
    portrait: `./assets/sukuna_shinjuku/skins/${r.tag}/portrait.png`, animationData: sksSkinAnim(r.tag) })),
]

// technique effect sheet for the equipped skin (premade), or null → the default fx sheet
export function sksSkinFx(f, key) {
  const tag = sksSkinTag(f?.skinId)
  return tag ? `./assets/sukuna_shinjuku/skins/${tag}/fx/${key}.png` : null
}
export function sksSkinPal(f) {
  const tag = sksSkinTag(f?.skinId)
  return tag && BY_TAG[tag].pal ? { ...SKS_DEFAULT_PAL, ...BY_TAG[tag].pal } : SKS_DEFAULT_PAL
}

// GLITTER (render-only): glint phase from the sim clock (8 sim frames per phase); swaps which pre-baked sheet the next
// body draw uses (same frame map → nothing about timing changes). Every phase is decoded first so a swap never blanks.
const _ready = new Set(), _warm = new Set()
export function sksSkinPhaseTick(f, simClock) {
  const tag = sksSkinTag(f?.skinId)
  if (!tag || !BY_TAG[tag].glitter) return
  if (!_warm.has(tag)) {
    _warm.add(tag)
    const paths = []; for (let q = 0; q < 3; q++) for (const d of Object.values(sksSkinAnim(tag, q))) if (d?.sheet) paths.push(d.sheet)
    preloadSheets(paths, r => { if (r?.ok) _ready.add(r.path) })
  }
  const p = Math.floor((simClock || 0) / 8) % 3
  if (f._sksGlintPhase === p) return
  const A = sksSkinAnim(tag, p), cur = A[f._lastSpriteAction || 'idle'] || A.idle
  if (p && cur?.sheet && !_ready.has(cur.sheet)) return
  f._sksGlintPhase = p; f._skinAnim = A
}
